<script>
(function () {
  'use strict';

  var form = document.getElementById('registro');
  // La validación nativa solo queda como respaldo si no hay JavaScript.
  form.noValidate = true;

  function el(id) { return document.getElementById(id); }

  var codificador = new TextEncoder();
  function octetos(texto) { return codificador.encode(texto).length; }

  /*
   * Comprueba un nombre de dominio ya convertido a A-labels (ASCII, minúsculas):
   * - nombre completo de 253 octetos como máximo;
   * - al menos dos etiquetas, cada una de 1 a 63 octetos (letras, cifras, guiones);
   * - TLD de dos o más letras, sin límite de longitud más allá de los 63 octetos
   *   de cualquier etiqueta (.corsica, .international), o una A-label xn-- (.xn--p1ai).
   * No se comprueba que el TLD exista: eso exige la lista de la IANA, no una lista fija.
   */
  function dominioAsciiValido(host) {
    if (host.length === 0 || host.length > 253) return false;
    var etiquetas = host.split('.');
    if (etiquetas.length < 2) return false;
    for (var i = 0; i < etiquetas.length; i++) {
      if (!/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(etiquetas[i])) return false;
    }
    var tld = etiquetas[etiquetas.length - 1];
    return /^(?:[a-z]{2,}|xn--[a-z0-9-]+)$/.test(tld);
  }

  /*
   * Convierte un dominio escrito por la persona (U-labels o A-labels, cualquier
   * combinación de mayúsculas y minúsculas) a A-labels con el analizador de URL
   * del navegador, que aplica UTS #46. Devuelve null si no es un dominio válido.
   */
  function dominioAAscii(dominio) {
    // Caracteres que el analizador de URL interpretaría como otra parte de la URL.
    if (dominio === '' || /[\s\/\\?#:@\[\]%]/.test(dominio)) return null;
    var host;
    try {
      host = new URL('http://' + dominio + '/').hostname;
    } catch (e) {
      return null;
    }
    return dominioAsciiValido(host) ? host : null;
  }

  function validarNombre(valor) {
    var v = valor.trim();
    if (v === '') return { error: 'Introduce tu nombre completo.' };
    if (!/\p{L}/u.test(v)) return { error: 'El nombre debe contener al menos una letra.' };
    return { error: '' };
  }

  function validarCorreo(valor) {
    var v = valor.trim();
    if (v === '') return { error: 'Introduce tu dirección de correo electrónico.' };

    var partes = v.split('@');
    if (partes.length !== 2) {
      return { error: 'La dirección debe contener una sola arroba (@).' };
    }
    var local = partes[0];
    var dominio = partes[1];

    // Parte local: cualquier carácter (Unicode incluido, RFC 6531), salvo espacios y controles.
    if (local === '') return { error: 'Falta el texto anterior a la arroba (@).' };
    if (/[\s\u0000-\u001f\u007f]/.test(local)) {
      return { error: 'El texto anterior a la arroba (@) no puede contener espacios.' };
    }
    if (octetos(local) > 64) {
      return { error: 'El texto anterior a la arroba (@) es demasiado largo.' };
    }

    if (dominio === '') return { error: 'Falta el dominio después de la arroba (@).' };
    var dominioAscii = dominioAAscii(dominio);
    if (dominioAscii === null) {
      return { error: 'El dominio de la dirección no es válido. Ejemplo: nombre@example.com' };
    }
    return { error: '', ascii: local + '@' + dominioAscii };
  }

  function validarSitio(valor) {
    var v = valor.trim();
    if (v === '') return { error: '', ascii: '' }; // campo opcional
    if (/\s/.test(v)) return { error: 'La dirección del sitio no puede contener espacios.' };

    // Si no se indica el esquema, se supone https://.
    var conEsquema = /^[a-z][a-z0-9+.\-]*:\/\//i.test(v) ? v : 'https://' + v;
    var url;
    try {
      url = new URL(conEsquema);
    } catch (e) {
      return { error: 'La dirección del sitio no es válida. Ejemplo: https://example.com' };
    }
    if (url.protocol !== 'http:' && url.protocol !== 'https:') {
      return { error: 'La dirección debe empezar por http:// o https://.' };
    }
    if (url.username !== '' || url.password !== '') {
      return { error: 'La dirección no debe incluir usuario ni contraseña.' };
    }
    // url.hostname ya está en A-labels y en minúsculas; se admite un punto final.
    if (!dominioAsciiValido(url.hostname.replace(/\.$/, ''))) {
      return { error: 'El nombre de dominio del sitio no es válido. Ejemplo: https://example.com' };
    }
    return { error: '', ascii: url.href };
  }

  function validarClave(valor) {
    if (valor === '') return { error: 'Introduce una contraseña.' };
    if (Array.from(valor).length < 8) {
      return { error: 'La contraseña debe tener al menos 8 caracteres.' };
    }
    return { error: '' };
  }

  var campos = [
    { input: el('nombre'), validar: validarNombre },
    { input: el('correo'), validar: validarCorreo, oculto: el('correo-ascii') },
    { input: el('sitio'),  validar: validarSitio,  oculto: el('sitio-ascii') },
    { input: el('clave'),  validar: validarClave }
  ];

  function comprobar(campo) {
    var resultado = campo.validar(campo.input.value);
    el(campo.input.id + '-error').textContent = resultado.error;
    if (resultado.error) {
      campo.input.setAttribute('aria-invalid', 'true');
    } else {
      campo.input.removeAttribute('aria-invalid');
    }
    // El valor escrito se envía tal cual; la forma convertida va en un campo oculto aparte.
    if (campo.oculto) campo.oculto.value = resultado.error ? '' : (resultado.ascii || '');
    return !resultado.error;
  }

  campos.forEach(function (campo) {
    campo.input.addEventListener('blur', function () { comprobar(campo); });
    campo.input.addEventListener('input', function () {
      // Mientras se corrige un campo marcado como no válido, el mensaje se actualiza al escribir.
      if (campo.input.getAttribute('aria-invalid') === 'true') comprobar(campo);
    });
  });

  form.addEventListener('submit', function (evento) {
    var primeroNoValido = null;
    campos.forEach(function (campo) {
      if (!comprobar(campo) && primeroNoValido === null) primeroNoValido = campo.input;
    });
    if (primeroNoValido !== null) {
      evento.preventDefault();
      primeroNoValido.focus();
    }
  });
})();
</script>
